import { sendMessageWithTabId } from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { captureMessage, initSentry } from "../../utils/sentry";

initSentry();

const overlay = document.getElementById(
  "brighthire-modal__root",
) as HTMLElement;

const appIframe = document.getElementById(
  "brighthire-modal__content",
) as HTMLIFrameElement;

const loadingSpinner = document.getElementById("brighthire-modal__loading");

const setSrc = (): void => {
  const urlParams = new URLSearchParams(window.location.search);
  const appUrl = urlParams.get("appUrl");
  if (appUrl == null) {
    captureMessage("Missing modal iframe appUrl");
    return;
  }
  appIframe.src = appUrl;
};

onDocumentLoaded(() => {
  setSrc();

  overlay.addEventListener("click", () => {
    sendMessageWithTabId({ action: "hideModal" });
  });

  // Hide the spinner once the inner iframe document loads — React's own
  // loading state takes over from there.
  if (loadingSpinner) {
    appIframe.addEventListener("load", () => {
      loadingSpinner.style.display = "none";
    });
  }
});
